def main():
    data = base64.b64decode(_IMAGE_B64)
    out = Path("/output/entry.png")
    try:
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_bytes(data)
    except OSError:
        out = Path("output") / "entry.png"
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_bytes(data)
    print(f"Wrote {len(data)} bytes to {out}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
